<template><q-page class="customer-flow-page"><div class="page-heading"><div><div class="eyebrow">EVERYDAY PAYMENTS</div><h1 class="page-title">Buy load</h1><p class="page-subtitle">Record a prepaid mobile-load purchase. This classroom system does not send credit to a telecom provider.</p></div><q-btn flat label="Refresh" icon="refresh" @click="load" /></div><q-banner v-if="error" class="bank-feedback q-mb-md">{{ error }}</q-banner><div class="customer-workspace-grid"><section class="customer-panel"><q-form class="customer-form" @submit="review = true"><q-select filled v-model="form.account_id" label="Pay from account" :options="accounts" emit-value map-options :rules="[required]" /><q-select filled v-model="form.network" label="Mobile network" :options="['Globe','Smart','DITO']" :rules="[required]" /><q-input filled v-model="form.mobile_number" label="Mobile number" inputmode="tel" maxlength="11" hint="11 digits starting with 09" :rules="[v => /^09[0-9]{9}$/.test(v) || 'Enter an 11-digit mobile number starting with 09']" /><q-select filled v-model="form.amount" label="Load amount (PHP)" :options="[25,50,100,200,300,500,1000]" :rules="[required]" /><q-btn color="primary" type="submit" label="Review purchase" :disable="!accounts.length || busy" /></q-form></section><section class="customer-panel"><h2 class="section-heading">Load history</h2><q-table flat :rows="rows" :columns="columns" row-key="id" :loading="loading" /></section></div><q-dialog v-model="review" persistent><q-card style="width:440px;max-width:95vw"><q-card-section><h2 class="section-heading">Confirm load purchase</h2><p>{{ form.network }} · {{ form.mobile_number }}</p><strong>PHP {{ form.amount }}</strong><p class="page-subtitle q-mt-md">The amount will be deducted from your simulated balance.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" :disable="busy" v-close-popup /><q-btn color="primary" label="Confirm purchase" :loading="busy" @click="purchase" /></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>
import { ref, onMounted } from 'vue'
import { useQuasar } from 'quasar'
import api from '@/services/api'
const $q = useQuasar(), accounts = ref([]), rows = ref([]), loading = ref(false), busy = ref(false), error = ref(''), review = ref(false)
const requestKey = () => Array.from(crypto.getRandomValues(new Uint8Array(16)), b => b.toString(16).padStart(2,'0')).join('')
const form = ref({account_id:null,network:'Globe',mobile_number:'',amount:100}), required = v => !!v || 'Required'
let pending = null, pendingBody = ''
const columns = [{name:'date',field:'created_at',label:'Date',align:'left'},{name:'network',field:'network',label:'Network'},{name:'number',field:'mobile_number',label:'Number'},{name:'amount',field:'amount',label:'PHP'},{name:'reference',field:'reference',label:'Reference'}]
async function load () { loading.value = true; error.value = '';  try { const [a,h] = await Promise.all([api.get('/customer/accounts/'),api.get('/customer/mobile-load/')]); accounts.value = a.data.filter(a=>a.status==='ACTIVE').map(a=>({label:a.account_number,value:a.id})); rows.value = h.data } catch { error.value = 'Could not load account data. Please refresh.' } finally { loading.value = false } }
async function purchase () { if(busy.value)return;busy.value=true;error.value='';try { const body=JSON.stringify(form.value);if(body!==pendingBody){pending=requestKey();pendingBody=body} const {data}=await api.post('/customer/mobile-load/',{...form.value,request_key:pending});review.value=false;pending=null;pendingBody='';await load();$q.dialog({title:'Load purchase recorded',message:`PHP ${data.amount} · ${data.mobile_number}\nReference: ${data.reference}`}) }catch(e){review.value=false;error.value=e.response?.data?.detail||'Could not confirm the purchase. Check history before retrying.'}finally{busy.value=false} }
onMounted(load)
</script>
